cd /dayjs && cat > /tmp/probe.js <<'EOF'
require('@babel/register');
const dayjs = require('./src').default;
const utc = require('./src/plugin/utc').default;
const timezone = require('./src/plugin/timezone').default;
dayjs.extend(utc); dayjs.extend(timezone);
const d = dayjs.tz('2014-06-01 12:00', 'America/New_York');
console.log('format:', d.format());
console.log('utcOffset:', d.utcOffset());
console.log('valueOf:', d.valueOf());
console.log('guess:', dayjs.tz.guess());
